scripts.completions.lua:
return function(ctx)
  local items, seen = {}, {}
  for word in ctx.document.text:gmatch('[%a_][%w_]+') do
    if not seen[word] and #items < 128 then
      seen[word] = true
      items[#items+1] = {label=word,range={start=ctx.request.position,finish=ctx.request.position},insert=word}
    end
  end
  return {result={completions=items}}
end

scripts.hover.lua:
return function(ctx)
  local p = ctx.request.position
  local line, col = hedit.to_utf16(p)
  return {result={hover={range={start=p,finish=p},text=('Line %d, UTF-16 column %d'):format(line+1,col+1)}}}
end

scripts.format.lua:
return function(ctx)
  local text = ctx.document.text:gsub('[ \t]+(\r?\n)', '%1'):gsub('[ \t]+$', '')
  return {result={formatting=hedit.replace(text)}}
end
